import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  const line1 = result.value.lines[0];
  assert.equal(line1.sku, 'DES-HOUR');
  assert.equal(line1.name, 'Design work (hour)');
  assert.equal(line1.qty, 5);
  assert.equal(line1.unitPrice, 8500);
  assert.equal(line1.vatRate, 21);

  const line2 = result.value.lines[1];
  assert.equal(line2.sku, 'DEV-HOUR');
  assert.equal(line2.name, 'Development (hour)');
  assert.equal(line2.qty, 3);
  assert.equal(line2.unitPrice, 9500);
  assert.equal(line2.vatRate, 21);
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice returns DATE_INVALID for invalid date format', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '10/07/2026',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice returns DATE_INVALID for non-existent dates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice returns DATE_INVALID for incomplete date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice returns NO_LINES for missing lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: undefined,
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice returns QTY_INVALID for zero quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice returns QTY_INVALID for negative quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice returns QTY_INVALID for non-integer quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice returns UNKNOWN_SKU for invalid SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'INVALID-SKU', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice stops at first error', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'INVALID-SKU', qty: 1 },
    ],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice does not mutate input lines', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const linesCopy = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });

  assert.deepEqual(lines, linesCopy);
});

test('createInvoice handles product with different VAT rate', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PRINT-A4', qty: 100 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 9);
});

test('createInvoice handles VAT exempt products', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 2 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 0);
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal works with qty of 1', () => {
  const line = { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 };
  assert.equal(lineTotal(line), 120000);
});

test('lineTotal works with large quantities', () => {
  const line = { sku: 'STICKER', name: 'Sticker sheet', qty: 10000, unitPrice: 50, vatRate: 21 };
  assert.equal(lineTotal(line), 500000);
});

test('invoiceTotals returns subtotal and total', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 8500 + 3 * 9500);
  assert.equal(totals.subtotal, 71000);
  assert.equal(totals.total, 71000);
});

test('invoiceTotals works with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'LOGO-PACK', name: 'Logo package', qty: 2, unitPrice: 120000, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 240000);
  assert.equal(totals.total, 240000);
});

test('invoiceTotals works with many lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 4, unitPrice: 9500, vatRate: 21 },
      { sku: 'COPY-HOUR', name: 'Copywriting (hour)', qty: 1, unitPrice: 6000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 2 * 8500 + 4 * 9500 + 1 * 6000);
  assert.equal(totals.subtotal, 61000);
  assert.equal(totals.total, 61000);
});

test('invoiceTotals total equals subtotal (no discounts or VAT yet)', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0 },
